function read({ keep, present: renamed, fallback = "field" } = {}) {
  return `${keep}:${renamed}:${fallback}`;
}

const arrow = ({ keep: alias = true } = {}) => `${alias}`;

function acquire(mode) {
  if (mode === 0) return { release: () => "plain" };
  if (mode === 1) return { release: ({ keep } = {}) => `${keep}` };
  return { release: ({ keep } = {}) => `${keep}` };
}

const holder = {
  release({ keep = true } = {}) {
    return `${keep}`;
  },
};

function invoke(callback) {
  return callback({ keep: false });
}

export function run() {
  const holderRelease = holder.release;
  const { release } = acquire(1);
  return [
    read(),
    read(undefined),
    read({}),
    read({ keep: false, present: "yes", fallback: undefined }),
    arrow(),
    arrow(undefined),
    arrow({}),
    arrow({ keep: false }),
    holderRelease === holder.release,
    invoke(holderRelease),
    release(),
    release(undefined),
    release({}),
    invoke(release),
  ].join("|");
}
